 data:{"Systems":[["System","Holds"],["Payroll","Salaries, bank details"],["Customer DB","Client financial documents"],["Source code","Product code"],["Email","Everyone's mail"],["Admin console","Cloud and user settings"],["Support desk","Client tickets"],["HR system","Employee records"],["Marketing tool","Newsletter lists"]]},
 problem:"Everyone currently has access to almost everything 'to save time'.",
 objective:"Set none/read/write/admin access for each role on each system, applying least privilege, and justify the sensitive cells.",
 deliverables:["Matrix: 6 roles × 8 systems","Justifications for every write/admin cell","Two risks the matrix reduces"],
 steps:[["Start from 'none'","Grant only what the job needs."],["Think 'what do they do daily?'","Accountant runs payroll; support reads tickets."],["Separate admin","Only IT Admin gets admin console access; admins use a separate admin account."],["Check segregation of duties","The person who approves payroll shouldn't also change bank details unchecked."],["Justify sensitive cells","One line each."]],
 rubric:[["Starts from least privilege (many 'none' cells)",1],["Only IT Admin has admin console access",1],["Developers have no production Customer DB write access by default",1],["Justifications for every write/admin cell",0],["Mentions segregation of duties",0]],
